return [{
    message: $node["Response Generator"].json["output"].slice(0,300) // Trim increased to 300 chars to acomodate VDP url
}];

// Helper to normalize use_replies_for_ai truthiness
// Helper: allow if flag is missing, block only if explicitly false
const shouldUseRepliesForAI = (val) => {
  // Flag does NOT exist → allow
  if (val === undefined || val === null) return true;

  // Flag exists → must be truthy
  return (
    val === true ||
    val === 'true' ||
    val === 1 ||
    val === '1' ||
    String(val).toLowerCase() === 'true'
  );
};

// Helper to normalize is_note truthiness
const isNoteTrue = (val) => {
  return val === true || val === 'true' || val === 1 || val === '1' || String(val).toLowerCase() === 'true';
};

// Helper to normalize internal_use truthiness
const isInternalTrue = (val) => {
  return val === true || val === 'true' || val === 1 || val === '1' || String(val).toLowerCase() === 'true';
};

// Helper to pick a note text field (fallback order)
const getNoteText = (json) => {
  return json.note || json.note_content || json.noteText || json.mail_content || json.message || null;
};

let contextArray = items.map((item, index) => {
  const status = (item.json.status || "").toString().trim().toLowerCase();
  const message = item.json.mail_content || item.json.message || null;
  const timestamp = item.json.timestamp || item.json.created_at || null;
  const response = item.json.api_response?.Response || null;

  const isNote = isNoteTrue(item.json.is_note);
  const isInternal = isInternalTrue(item.json.internal_use);
  const useRepliesForAI = shouldUseRepliesForAI(item.json.use_replies_for_ai);

  // EXCLUDE if use_replies_for_ai does not exist or is false
  if (!useRepliesForAI) {
    return null;
  }

  // EXCLUDE internal notes
  if (isNote && isInternal) {
    return null;
  }

  if (status === "received" && message && timestamp) {
    return `Conversation ${index + 1}:\nMessage (Received): "${message}"\nCreated At: "${timestamp}"`;
  } 
  else if (status === "sent" && message && timestamp) {
    let combined = `Conversation ${index + 1}:\nMessage (Sent): "${message}"`;
    if (response) {
      combined += `\nAPI Response: "${response}"`;
    }
    combined += `\nCreated At: "${timestamp}"`;
    return combined;
  } 
  else if (status === "failed" && message && timestamp) {
    return `Conversation ${index + 1}:\nMessage (Failed to Send): "${message}"\nCreated At: "${timestamp}"`;
  } 
  else {
    return null; // Skip if not enough info
  }
}).filter(Boolean);

let contextString = contextArray.length > 0 ? contextArray.join("\n\n") : null;

// Extract lead_id from the *first* item only (same behavior as before)
let leadId = items.length > 0 ? items[0].json.lead_id : null;

// NEW: extract items where is_note is true
const noteItems = items
  .map((it, idx) => ({ json: it.json, idx })) // keep index if needed
  .filter(it =>
    shouldUseRepliesForAI(it.json.use_replies_for_ai) &&
    isNoteTrue(it.json.is_note) &&
    !isInternalTrue(it.json.internal_use)
  );

const leadNotes = noteItems.map((it, i) => {
  const noteText = getNoteText(it.json);
  const ts = it.json.timestamp || it.json.created_at || null;
  // Build a structured note object
  return {
    note_index: it.idx,
    note_text: noteText,
    created_at: ts,
    raw: it.json // keep raw payload in case you need other fields
  };
}).filter(n => n.note_text); // drop notes without any text

// A joined single string representation (useful for prompts)
const leadNotesText = leadNotes.length > 0
  ? leadNotes.map((n, i) => `Note ${i+1}:\n"${n.note_text}"${n.created_at ? `\nCreated At: "${n.created_at}"` : ''}`).join("\n\n")
  : null;

return [{
  json: {
    context: contextString,
    lead_id: leadId,
    lead_notes: leadNotes,         // structured array of notes
    lead_notes_text: leadNotesText // single string for quick use
  }
}];

