const availability = $json?.dealer_account_information?.weekly_availability;

if (!availability) {
  return {
    store_hours_text: "No available store hours at the moment."
  };
}

const dayNames = {
  monday: "Monday",
  tuesday: "Tuesday",
  wednesday: "Wednesday",
  thursday: "Thursday",
  friday: "Friday",
  saturday: "Saturday",
  sunday: "Sunday"
};

let formattedHours = [];

for (const day in availability) {
  const info = availability[day];
  if (info.active && info.start && info.end) {
    formattedHours.push(`${dayNames[day]}: ${info.start}–${info.end}`);
  }
}

return [{
  json: {
    store_hours_text: formattedHours.join(", ")
  }
}];

const attachments =
  $node["Extract Attachments"]?.json?.attachments || [];
const attachment_index = {
  images: [],
  videos: [],
  documents: [],
  audio: [],
  archives: [],
  others: []
};

for (const a of attachments) {
  const name = (a.filename || "").toLowerCase();
  const type = (a.contentType || a.content_type || "").toLowerCase();

  if (type.startsWith("image/") || name.match(/\.(jpg|jpeg|png|webp|gif)$/i)) {
    attachment_index.images.push(a);
    continue;
  }

  if (type.startsWith("video/") || name.match(/\.(mp4|mov|avi|mkv)$/i)) {
    attachment_index.videos.push(a);
    continue;
  }

  if (
    type === "application/pdf" ||
    type.startsWith("text/") ||
    name.match(/\.(pdf|txt|csv|doc|docx|xls|xlsx|ppt|pptx)$/i)
  ) {
    attachment_index.documents.push(a);
    continue;
  }

  if (type.startsWith("audio/") || name.match(/\.(mp3|wav|m4a|aac)$/i)) {
    attachment_index.audio.push(a);
    continue;
  }

  if (name.match(/\.(zip|rar|7z)$/i)) {
    attachment_index.archives.push(a);
    continue;
  }

  attachment_index.others.push(a);
}

return [{
  ...$json,
  attachment_index
}];

const idx =
  $node["Classify Attachments"]?.json?.attachment_index;
const flat = [];

for (const a of idx.images)     flat.push({ ...a, modality: "image" });
for (const a of idx.documents)  flat.push({ ...a, modality: "document" });
for (const a of idx.videos)     flat.push({ ...a, modality: "video" });
for (const a of idx.audio)      flat.push({ ...a, modality: "audio" });
for (const a of idx.archives)   flat.push({ ...a, modality: "archive" });
for (const a of idx.others)     flat.push({ ...a, modality: "other" });

return flat.map(a => ({ json: a }));

const raw = $json.content?.[0]?.text || "";

const cleaned = raw
  .replace(/^```json\s*/i, "")
  .replace(/```$/i, "")
  .trim();

let parsed;
try {
  parsed = JSON.parse(cleaned);
} catch (e) {
  throw new Error("Invalid JSON from image analyzer");
}

return [{
  modality: "image",
  filename: $json.filename,
  insights: parsed
}];

const i = $json.insights;

return [{
  modality: "image",
  filename: $json.filename,
  insights: {
    vehicle_present: i.vehicle_present ?? false,
    vehicle_type: i.vehicle_type ?? null,
    brand: i.brand_visible ?? null,
    visible_damage: i.visible_damage ?? null,
    confidence: i.confidence ?? null
  }
}];

const items = $items(); // safe even if empty

const image_insights = [];
const document_insights = [];

for (const item of items) {
  const d = item.json || {};

  if (d.modality === "image") {
    image_insights.push({
      filename: d.filename || null,
      insights: d.insights || null
    });
  }

  if (d.modality === "document") {
    document_insights.push({
      filename: d.filename || null,
      insights: d.insights || null
    });
  }
}

// ALWAYS return exactly ONE item
return [{
  image_insights,
  document_insights,
  has_attachments: image_insights.length + document_insights.length > 0
}];

const agg = $node["Aggregate AI Insights"]?.json;

const images = agg?.image_insights || [];
const docs = agg?.document_insights || [];

let context = "";

if (images.length > 0) {
  context += "IMAGE ANALYSIS:\n";
  images.forEach((img, i) => {
    context += `Image ${i + 1}: ${JSON.stringify(img.insights)}\n`;
  });
}

if (docs.length > 0) {
  context += "\nDOCUMENT ANALYSIS:\n";
  docs.forEach((doc, i) => {
    context += `Document ${i + 1}: ${JSON.stringify(doc.insights)}\n`;
  });
}

return [{
  combined_context: context.trim() || null,
  has_attachments: agg?.has_attachments ?? false
}];

// Pick the correct source object
const sms = $node["SMS Trigger"].json.body.currentMessage || {};

// Normalize attachments safely
const attachments = (sms.attachments || []).map(a => ({
  filename: a.filename || null,
  content_type: a.contentType || null,
  size: a.size || null,
  url: a.url || null,
  s3_key: a.s3Key || null,
  uploaded_at: a.uploadedAt || null
}));

return [{
  json: {
    sender: sms.sender || null,
    subject: sms.subject || null,
    dealer_id: sms.dealer_id || null,

    // 🔑 THIS IS WHAT YOU USE IN IF NODE
    has_attachments: attachments.length > 0,

    attachments
  }
}];

const buffer = Buffer.from($binary.data.data, "base64");
const text = buffer.toString("utf-8");

return [{
  extracted_text: text
}];

const buffer = Buffer.from($binary.data.data, "base64");
const text = buffer.toString("utf-8");

return [{
  extracted_text: text
}];

const frames = items.map(i => i.json);

return [{
  video_intelligence: {
    frames_analyzed: frames.length,
    damage_detected: frames.some(f => f.visible_damage?.present),
    avg_confidence:
      frames.reduce((a,f)=>a+(f.confidence||0),0)/(frames.length||1)
  }
}];

const campaignIdSet = new Set();

for (const item of items) {
  if (item.json.campaign_id) {
    campaignIdSet.add(item.json.campaign_id);
  }
}

const campaignObjectIds = Array.from(campaignIdSet).map(id => ({
  $oid: id
}));

return [{
  json: {
    campaign_ids: Array.from(campaignIdSet),       // keep string version (optional)
    campaign_object_ids: campaignObjectIds          // ObjectId version for MongoDB
  }
}];

let latestCampaign = null;
let latestTs = 0;

for (const item of items) {
  const campaign = item.json;

  const ts =
    new Date(
      campaign?.message_content?.sent_at ||
      campaign?.sent_at ||
      campaign?.created_at ||
      0
    ).getTime();

  if (ts > latestTs) {
    latestTs = ts;
    latestCampaign = campaign;
  }
}

return [{
  json: {
    has_campaign_context: !!latestCampaign,
    campaign_id: latestCampaign?._id || null,
    campaign_name: latestCampaign?.name || null,

    // SMS-specific extraction
    campaign_subject: latestCampaign?.message_content?.subject || null,
    campaign_body: latestCampaign?.message_content?.body || null,

    campaign_sent_at:
      latestCampaign?.message_content?.sent_at

